package ama.storage;
import java.util.*;import java.nio.file.*;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import static org.junit.jupiter.api.Assertions.*;
/** Read-only exact terminal discovery after the failed GET-count assertion; no app/provider/worker/native. */
class Task11B1MemberFactsIT {
 @Test void exactGeneratedCandidateAndReservationRemainDurablyTerminal()throws Exception {
  assertEquals("task11-fix02-isolated",System.getenv("AMA_TASK11_FIXTURE"));var j=new JdbcTemplate(ama.publication.Task11Source.open());String meeting="a6e5a40e-6314-4ef9-9e57-d4fcb4982e5e",task="d674179a-2986-4411-b4d3-d07cba9589ea";
  var rows=j.queryForList("SELECT t.id task_id,t.state task_state,t.subject_id,t.business_version,e.id execution_id,e.state execution_state,e.request_hash,o.id operation_id,o.state operation_state,o.external_result_id,r.id reservation_id,r.settled_at,c.id candidate_id,c.input_id,c.input_fingerprint,c.state candidate_state,c.minutes_revision_id,c.element_set_id FROM durable_task t JOIN external_execution e ON e.task_id=t.id JOIN external_operation o ON o.id=e.operation_id JOIN model_reservation r ON r.execution_id=e.id JOIN generation_candidate c ON c.task_id=t.id WHERE t.id=? AND t.subject_kind='MEETING' AND t.subject_id=?",task,meeting);assertEquals(1,rows.size());var row=rows.getFirst();for(String state:List.of("task_state","execution_state","operation_state"))assertEquals("SUCCEEDED",row.get(state));assertEquals("PENDING",row.get("candidate_state"));assertNotNull(row.get("settled_at"));assertTrue(row.get("external_result_id").toString().startsWith("cmr-"));assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM publication WHERE meeting_id=?",Integer.class,meeting));assertEquals(1,j.queryForObject("SELECT COUNT(*) FROM model_reservation WHERE execution_id=?",Integer.class,row.get("execution_id")));
  var safe=new TreeMap<String,Object>();row.forEach((key,value)->safe.put(key,value instanceof java.time.temporal.TemporalAccessor||value instanceof java.util.Date?value.toString():value));safe.put("qualification","Durable state/result binding/settled reservation observed directly. Prior relay countsPOST1/GET1; result fetch URI inferred from exact successful client source, not captured directly by relay.");safe.put("expectedSuccessfulResultFetchPath","/v1/minutes/results/"+row.get("external_result_id"));Files.writeString(Path.of(System.getenv("AMA_TASK11_EVIDENCE_WINDOW"),"exact-terminal-facts.json"),new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(safe));
 }
}
